// Mirrors crates/ekko-core (settings.rs, notch.rs). Will be generated by tauri-specta in F2.

export type DisplayMode = 'notch' | 'tray' | 'orb' | 'dock' | 'hub' | 'voice-only'
export type Persona = 'ekko' | 'ultron' | 'eco'
export type DockSide = 'left' | 'right'
export type NotchSize = 'compact' | 'normal' | 'large'
export type NotchOpen = 'hover' | 'click'
export type NotchIdle = 'pill' | 'minimal'

export interface NotchSettings {
  /** Horizontal center as a fraction of the monitor width (0.5 = centered). */
  offset: number
  size: NotchSize
  openOn: NotchOpen
  hoverDelayMs: number
  idle: NotchIdle
}

export const DEFAULT_NOTCH: NotchSettings = {
  offset: 0.5,
  size: 'normal',
  openOn: 'hover',
  hoverDelayMs: 180,
  idle: 'pill',
}

export interface MonitorInfo {
  index: number
  name: string
  width: number
  height: number
  primary: boolean
}

export interface Settings {
  version: number
  userName: string
  assistantName: string
  displayMode: DisplayMode
  persona: Persona
  dockSide: DockSide
  monitor: number
  orbPosition: [number, number] | null
  notch: NotchSettings
  /** False until the welcome flow is finished. */
  onboarded: boolean
}

export const DEFAULT_SETTINGS: Settings = {
  version: 1,
  userName: 'Guilherme',
  assistantName: 'Ekko',
  displayMode: 'notch',
  persona: 'ekko',
  dockSide: 'right',
  monitor: 0,
  orbPosition: null,
  notch: DEFAULT_NOTCH,
  onboarded: false,
}

/** Overlay area that must receive the mouse, logical px relative to the window. */
export interface HitRect {
  x: number
  y: number
  w: number
  h: number
  /** Increasing counter so the backend can drop out-of-order updates. */
  seq?: number
}

export type Unlisten = () => void

/** Everything the UI may ask from the backend. Real (Tauri) or mock (browser/prototype). */
export interface Backend {
  readonly kind: 'tauri' | 'mock'
  getSettings(): Promise<Settings>
  onSettingsChanged(cb: (s: Settings) => void): Promise<Unlisten>
  setDisplayMode(mode: DisplayMode): Promise<void>
  setPersona(persona: Persona): Promise<void>
  setDockSide(side: DockSide): Promise<void>
  setNames(userName: string, assistantName: string): Promise<void>
  openSettings(): Promise<void>
  summon(): Promise<void>
  showPanelBesideOrb(): Promise<void>
  /** Overlay windows (notch, dock) report their visible part for click-through. */
  setHitRect(rect: HitRect): Promise<void>
  onHover(cb: (inside: boolean) => void): Promise<Unlisten>
  onSummon(cb: () => void): Promise<Unlisten>
  /** Cross-window broadcast (mock assistant state lives in every window). */
  broadcast<T>(event: string, payload: T): Promise<void>
  listen<T>(event: string, cb: (payload: T) => void): Promise<Unlisten>
  setNotch(notch: NotchSettings): Promise<void>
  listMonitors(): Promise<MonitorInfo[]>
  setMonitor(index: number): Promise<void>
  /** Notch drag along the top edge. `dx` (CSS px since start) is used by the mock only;
   * Tauri follows the real cursor. */
  notchDrag(phase: 'start' | 'move' | 'end', dx: number): Promise<void>
  /** Pill center inside the notch window (logical px); null until placed. */
  getNotchAnchor(): Promise<number | null>
  onNotchAnchor(cb: (anchor: number) => void): Promise<Unlisten>
  onFocusChanged(cb: (focused: boolean) => void): Promise<Unlisten>
  focusSelf(): Promise<void>
  togglePalette(): Promise<void>
  onPaletteOpen(cb: () => void): Promise<Unlisten>
  openOnboarding(): Promise<void>
  finishOnboarding(): Promise<void>
  /** Opens the on-screen alarm window with any JSON alarm object. */
  showAlarm<T>(alarm: T): Promise<void>
  /** The alarm the alarm window was opened for (null if already taken). */
  takeAlarm<T>(): Promise<T | null>
  onAlarm<T>(cb: (alarm: T) => void): Promise<Unlisten>
  hideSelf(): Promise<void>
  startDragging(): Promise<void>
}
